import React, { useState } from "react";
import * as XLSX from "xlsx";
import { saveAs } from "file-saver";
import costoStandardData from "../costi_standard.json";
import "../styles/forms.css";
import "../styles/buttons.css";

export default function ProgrammaEsecutivo() {
  const [selected, setSelected] = useState(null);
  const [descrizione, setDescrizione] = useState("");
  const [tipo, setTipo] = useState("");
  const [quantita, setQuantita] = useState(1);
  const [esecuzione, setEsecuzione] = useState("");
  const [righe, setRighe] = useState([]);

  const currencyFormatter = new Intl.NumberFormat("it-IT", {
    style: "currency",
    currency: "EUR",
  });

  const handleSelect = (code) => {
    const az = costoStandardData.find((a) => a.azioneOperativa === code);
    setSelected(az || null);
    setDescrizione("");
    setTipo("");
    setQuantita(1);
  };

  const calcolaValore = (base) => {
    return quantita && !isNaN(quantita) ? base * parseInt(quantita) : 0;
  };

  const costoTotale =
    (selected ? calcolaValore(selected.personale) : 0) +
    (selected ? calcolaValore(selected.materiali) : 0) +
    (selected ? calcolaValore(selected.noli || 0) : 0);

  const aggiungiRiga = () => {
    if (!selected) return;
    const nuovaRiga = {
      "Azione Operativa": selected.azioneOperativa,
      "Descrizione Intervento": descrizione,
      "Tipo Intervento": tipo,
      Quantità: quantita,
      Esecuzione: esecuzione,
      "UM": selected.um,
      "Personale (€)": selected.personale,
      "Materiali (€)": selected.materiali,
      "Noli (€)": selected.noli,
      "Costo Totale (€)": costoTotale,
    };

    setRighe([...righe, nuovaRiga]);
  };

  const salvaSuSharePoint = () => {
    if (righe.length === 0) {
      alert("Non ci sono dati da salvare!");
      return;
    }

    // Creazione del foglio Excel
    const ws = XLSX.utils.json_to_sheet(righe);
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, "ProgrammaEsecutivo");

    const wbout = XLSX.write(wb, { bookType: "xlsx", type: "array" });
    const blob = new Blob([wbout], {
      type: "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
    });

    saveAs(blob, "ProgrammaEsecutivo.xlsx");
    alert("✅ File Excel generato e scaricato correttamente!");
  };

  return (
    <div className="programma-esecutivo p-4 max-w-6xl mx-auto">
      <h2 className="text-2xl font-bold mb-4">Programma Esecutivo</h2>

      <div className="grid grid-cols-2 gap-4 bg-gray-50 p-4 rounded-xl shadow-md">
        <div>
          <label>Azione Operativa</label>
          <select
            className="form-control"
            onChange={(e) => handleSelect(e.target.value)}
            value={selected?.azioneOperativa || ""}
          >
            <option value="">-- Seleziona --</option>
            {costoStandardData.map((a, idx) => (
              <option key={idx} value={a.azioneOperativa}>
                {a.azioneOperativa} - {a.descrizione}
              </option>
            ))}
          </select>
        </div>

        <div>
          <label>Descrizione sintetica</label>
          <input
            className="form-control"
            value={descrizione}
            onChange={(e) => setDescrizione(e.target.value)}
          />
        </div>

        <div>
          <label>Tipo</label>
          <input
            className="form-control"
            value={tipo}
            onChange={(e) => setTipo(e.target.value)}
          />
        </div>

        <div>
          <label>Quantità</label>
          <input
            type="number"
            className="form-control"
            value={quantita}
            onChange={(e) => setQuantita(e.target.value)}
          />
        </div>

        <div>
          <label>Esecuzione</label>
          <select
            className="form-control"
            value={esecuzione}
            onChange={(e) => setEsecuzione(e.target.value)}
          >
            <option value="">-- Seleziona --</option>
            <option value="Amministrazione Diretta">Amministrazione Diretta</option>
            <option value="Appalto">Appalto</option>
          </select>
        </div>
      </div>

      <div className="mt-4 flex gap-4">
        <button className="btn btn-success" onClick={aggiungiRiga}>
          ➕ Aggiungi alla tabella
        </button>

        <button className="btn btn-primary" onClick={salvaSuSharePoint}>
          💾 Esporta Excel
        </button>
      </div>

      <table className="table mt-6">
        <thead>
          <tr>
            <th>Azione</th>
            <th>Descrizione</th>
            <th>Tipo</th>
            <th>Quantità</th>
            <th>Esecuzione</th>
            <th>UM</th>
            <th>Personale</th>
            <th>Materiali</th>
            <th>Noli</th>
            <th>Totale</th>
          </tr>
        </thead>
        <tbody>
          {righe.map((r, i) => (
            <tr key={i}>
              <td>{r["Azione Operativa"]}</td>
              <td>{r["Descrizione Intervento"]}</td>
              <td>{r["Tipo Intervento"]}</td>
              <td>{r.Quantità}</td>
              <td>{r.Esecuzione}</td>
              <td>{r.UM}</td>
              <td>{currencyFormatter.format(r["Personale (€)"])}</td>
              <td>{currencyFormatter.format(r["Materiali (€)"])}</td>
              <td>{currencyFormatter.format(r["Noli (€)"])}</td>
              <td>{currencyFormatter.format(r["Costo Totale (€)"])}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}
